package main

import (
	"context"
	"encoding/json"
	"log/slog"
	"time"

	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/internal/mirrorjobs"
	"github.com/entirehq/mirror-pipeline/pkg/fanoutengine"
	"github.com/entirehq/mirror-pipeline/pkg/gitjobs"
)

// syncResolver resolves GitHub push webhooks into mirror.git sync_repo routes,
// one per resolved mirror placement. It is the engine's Resolver: it describes
// WHERE each sync job goes (gitSyncRoute) and lets the engine own the per-region
// publish + partial-failure aggregation.
//
// fanout no longer derives GitHub installation/repo metadata jobs from webhooks:
// entire-core-global consumes webhooks_github_v1 directly for that (COR-523).
// Only the push -> sync_repo routing remains here — the one path that needs
// Core.LookupByMirror.
type syncResolver struct {
	routes routeResolver
}

func newSyncResolver(routes routeResolver) *syncResolver {
	return &syncResolver{routes: routes}
}

// asInputError reports whether err is a fanoutengine.InputError — a malformed
// input body (bad JSON, unparseable repo full_name) the engine terminates
// without redelivery. Aliased so the resolver tests keep their local name.
var asInputError = fanoutengine.AsInputError

// Resolve returns one sync_repo route per resolved mirror placement. Two
// events fan out: `push` (the source moved refs) and a `repository` edit that
// changed the default branch (ENT-1133 — a default-branch change to an
// existing branch produces no push, so a normal sync never sees it; routing it
// here lets the worker's post-sync followSourceHEAD reconcile the mirror's
// default). Every other event is a no-op (empty slice -> Ack): their
// installation/repo metadata is mirrored by entire-core-global's direct
// webhooks_github_v1 consumer (COR-523). deliveryID/observedAt are part of the
// Resolver contract but unused here. Returns an *InputError for malformed input
// (the engine Terminates) or a plain error for a transient Core route lookup
// failure (the engine Naks so JetStream redelivers).
func (d *syncResolver) Resolve(ctx context.Context, event string, _ string, _ time.Time, body []byte) ([]fanoutengine.Route, string, error) {
	switch event {
	case "push":
		routes, err := d.push(ctx, body)
		return routes, "", err // fanout doesn't distinguish ack reasons
	case "repository":
		routes, err := d.repositoryDefaultBranchEdit(ctx, body)
		return routes, "", err
	default:
		return nil, "", nil
	}
}

func (d *syncResolver) push(ctx context.Context, body []byte) ([]fanoutengine.Route, error) {
	var payload webhookPushPayload
	if err := json.Unmarshal(body, &payload); err != nil {
		return nil, fanoutengine.Input("invalid JSON")
	}
	return d.routesForRepo(ctx, payload.Repository, payload.Installation.ID)
}

// repositoryDefaultBranchEdit fans out a reconcile sync only for a `repository`
// edit that changed the default branch (action=="edited" with a non-nil
// changes.default_branch). The resulting sync applies no refs but its
// followSourceHEAD moves the mirror's HEAD to the source's new default. Any
// other repository action, or an edit that didn't touch the default branch, is
// a benign no-op (nil routes -> Ack) — so this doesn't churn a sync on every
// description edit, visibility change, etc.
func (d *syncResolver) repositoryDefaultBranchEdit(ctx context.Context, body []byte) ([]fanoutengine.Route, error) {
	var payload webhookRepositoryPayload
	if err := json.Unmarshal(body, &payload); err != nil {
		return nil, fanoutengine.Input("invalid JSON")
	}
	if payload.Action != "edited" || payload.Changes == nil || payload.Changes.DefaultBranch == nil {
		return nil, nil // not a default-branch change: nothing to reconcile
	}
	return d.routesForRepo(ctx, payload.Repository, payload.Installation.ID)
}

// routesForRepo resolves the mirror placement(s) for a source repo and returns
// one sync route per placement. Shared by the push and default-branch-edit
// paths: the sync job is keyed by source coordinates + placement, not by any
// ref, so both events build the identical job.
func (d *syncResolver) routesForRepo(ctx context.Context, repo webhookRepository, installationID int64) ([]fanoutengine.Route, error) {
	fullName := repo.FullName
	owner, name, ok := gitjobs.SplitFullName(fullName)
	if !ok {
		return nil, fanoutengine.Input("invalid repository full_name: %s", fullName)
	}

	// Stamp the parent webhook span with the source coordinates so failed or
	// no-op deliveries (unknown repo, route resolution failure) are still
	// findable in Honeycomb by entire.source_owner/repo.
	trace.SpanFromContext(ctx).SetAttributes(
		attribute.String("entire.source_kind", string(gitjobs.SourceKindGithub)),
		attribute.String("entire.source_owner", owner),
		attribute.String("entire.source_repo", name),
	)

	src := sourceEvent{
		Kind:         gitjobs.SourceKindGithub,
		Owner:        owner,
		Repo:         name,
		AuthRef:      gitjobs.FormatGithubInstallationAuthRef(installationID),
		GitHubRepoID: repo.ID,
	}
	routes, err := d.routes.RoutesForSource(ctx, src)
	if err != nil {
		slog.ErrorContext(ctx, "Route resolution failed",
			slog.String("repo", fullName), slog.Any("error", err))
		return nil, err
	}

	if len(routes) == 0 {
		// Webhook arrived for a repo entire-core has no mirror placement
		// for. GitHub App is installed but `entiredb create mirror` was
		// never run (or has been removed). Surface this as a first-class
		// outcome so operators can search by source_repo. Empty routes ->
		// the engine Acks (benign no-op).
		span := trace.SpanFromContext(ctx)
		span.SetAttributes(attribute.Bool("entire.mirror.unknown_repo", true))
		span.AddEvent("mirror.unknown_repo")
		slog.WarnContext(ctx, "Webhook received for repo with no mirror placement",
			slog.String("source_owner", owner),
			slog.String("source_repo", name),
			slog.Int64("installation_id", installationID))
		return nil, nil
	}

	// One route per resolved placement. The engine publishes them all and Naks
	// if any fails (the successful ones re-run idempotently on redelivery via
	// their Nats-Msg-Id), so a single unroutable placement no longer starves the
	// others — that partial-failure aggregation now lives in the engine.
	out := make([]fanoutengine.Route, 0, len(routes))
	for _, route := range routes {
		out = append(out, gitSyncRoute{route: route})
	}
	return out, nil
}

// gitSyncRoute publishes one mirror.git sync_repo job into a placement's region.
// Region() is the target cluster_id; Publish delegates to the unchanged
// mirrorjobs publisher over the engine-resolved region handle, so the producer
// span, Nats-Msg-Id dedup key, payload, and trace-context injection are all
// preserved verbatim.
type gitSyncRoute struct {
	route mirrorRoute
}

func (r gitSyncRoute) Region() string { return r.route.Placement.ClusterID }

func (r gitSyncRoute) Publish(ctx context.Context, js fanoutengine.PublishJS) error {
	return mirrorjobs.NewPublisher(js).PublishGitSyncJob(ctx, r.route)
}

