// Package gitjobs defines the target-owned Git mirror job contract.
package gitjobs

import (
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"net/url"
	"reflect"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel/attribute"
)

const (
	StreamName    = "mirror_git_v1"
	SubjectPrefix = "mirror.git.v1."
	Version1      = 1

	// StreamDuplicatesWindow is the JetStream dedup window. Publishes that
	// reuse the same Nats-Msg-Id within this window are collapsed server-side
	// to a single stored message. Scoped to collapse the webhook fan-out burst
	// from a single source change; long-tail races are handled by route-level
	// coalescing in the ingest (see Task 6).
	StreamDuplicatesWindow = 1 * time.Second

	// StreamMaxAge bounds how long an unacked job can sit in the stream
	// before JetStream drops it server-side. 6h is the tightest window
	// that survives a realistic worker outage. NOTE: the periodic resync
	// scheduler that used to backstop drops past this window has been
	// decommissioned, so a job aged out here is only recovered by the next
	// webhook for that source (or a manual resync) — not automatically.
	StreamMaxAge = 6 * time.Hour

	// StreamMaxBytes caps the on-disk footprint per replica. With
	// Discard=DiscardNew, hitting this rejects new publishes (the
	// webhook returns 500) instead of silently dropping already-enqueued
	// jobs. ~500B payloads => ~2M queued jobs per replica; cluster total
	// at R=3 is 3× this.
	StreamMaxBytes = 1 << 30 // 1 GiB

	// DefaultStreamReplicas is the production target. Single-node dev
	// NATS overrides via ENTIRE_NATS_STREAM_REPLICAS=1.
	DefaultStreamReplicas = 3
)

type SourceKind string
type Op string

const (
	SourceKindGithub   SourceKind = "github"
	SourceKindEntireDB SourceKind = "entiredb"
	// SourceKindEntireDBNamespace is an entiredb sync scoped to the
	// Entire-owned refs/heads/entire/native/* namespace (COR-1566): same
	// body shape as entiredb, different replication scope on the worker,
	// and its own subject token so the two kinds land on separate durables.
	SourceKindEntireDBNamespace SourceKind = "entiredb_ns"

	OpSyncRepo Op = "sync_repo"

	GithubAppInstallationAuthRefPrefix = "github_app_installation:"
)

// Placement is the target cluster identity used to compose the message
// subject. It is not on the wire — every published message carries its
// placement in the subject (mirror.git.v1.<jur>.<cluster>.<src>.<op>), so
// consumers recover it via ParseSubject(msg.Subject).
type Placement struct {
	Jurisdiction string
	ClusterID    string
}

// ParsedSubject is the inverse of Subject: everything the message subject
// encodes. Consumers use this to recover placement / source kind / op
// without trusting the body, since the broker routed by subject.
type ParsedSubject struct {
	Placement  Placement
	SourceKind SourceKind
	Op         Op
}

type Target struct {
	ULID string `json:"ulid"`
}

type Source struct {
	// Owner/Repo are the GitHub upstream coordinates. github kind only.
	Owner   string `json:"owner,omitempty"`
	Repo    string `json:"repo,omitempty"`
	AuthRef string `json:"auth_ref,omitempty"`
	// URL is the source repo's internal by-ID git URL on its home entiredb
	// cluster (https://<internal host>/git/repo/<ULID>), computed by
	// entire-core so fanout and the worker stay source-agnostic. entiredb
	// kind only; the worker additionally gates the host against its
	// configured source-cluster allowlist before fetching — schema
	// validation here bounds the shape, not the trust.
	URL string `json:"url,omitempty"`
}

type Job struct {
	Version int    `json:"version"`
	Source  Source `json:"source"`
	Target  Target `json:"target"`
}

		return job, fmt.Errorf("validate git job: %w", err)
	}
	if err := job.ValidateFor(kind); err != nil {
		return job, fmt.Errorf("validate git job: %w", err)
	}
	return job, nil
}

// MsgID composes the JetStream dedup id for a job: source coordinates +
// target, per kind — github keys on the upstream owner/repo, entiredb on the
// source repo ULID. Shared by every publisher so retries and the duplicate
// window collapse identically no matter who published.
func MsgID(parsed ParsedSubject, job Job) string {
	if parsed.SourceKind == SourceKindEntireDB || parsed.SourceKind == SourceKindEntireDBNamespace {
		return fmt.Sprintf("%s/%s/%s/%s", parsed.Op, parsed.SourceKind, job.Source.SourceRepoULID(), job.Target.ULID)
	}
	return fmt.Sprintf("%s/%s/%s/%s/%s", parsed.Op, parsed.SourceKind, job.Source.Owner, job.Source.Repo, job.Target.ULID)
}

// EnsureStream is idempotent: create the stream if it's absent, otherwise
// reconcile any drift in the contract fields (including a Replicas scale-up
// — supported online by nats-server >= 2.8). Replicas comes from the caller
// so dev (single-node NATS) can pass 1 via ENTIRE_NATS_STREAM_REPLICAS.
// ParseStreamReplicas parses a replica count from a raw env-var string.
// Empty input returns DefaultStreamReplicas (production target). Any other
// input must be a positive integer; zero, negative, or non-integer values
// are rejected so a typo in deploy config fails fast at startup instead of
// silently shipping a single-replica stream.
func ParseStreamReplicas(raw string) (int, error) {
	if raw == "" {
		return DefaultStreamReplicas, nil
	}
	n, err := strconv.Atoi(raw)
	if err != nil {
		return 0, fmt.Errorf("invalid replica count %q: %w", raw, err)
	}
	if n < 1 {
		return 0, fmt.Errorf("invalid replica count %d: must be >= 1", n)
	}
	return n, nil
}

func EnsureStream(js nats.JetStreamContext, replicas int) error {
	desired := ownedStreamConfig(replicas)

	_, err := js.AddStream(desired)
	if err == nil {
		return nil
	}
	if !errors.Is(err, nats.ErrStreamNameAlreadyInUse) {
		return fmt.Errorf("create git mirror stream: %w", err)
	}

	existing, err := js.StreamInfo(StreamName)
	if err != nil {
		return fmt.Errorf("get git mirror stream: %w", err)
	}

	updated := existing.Config
	applyContract(&updated, replicas)
	if reflect.DeepEqual(updated, existing.Config) {
		return nil
	}

	if _, err = js.UpdateStream(&updated); err != nil {
		return fmt.Errorf("update git mirror stream: %w", err)
	}
	return nil
}

func ownedStreamConfig(replicas int) *nats.StreamConfig {
	cfg := &nats.StreamConfig{}
	applyContract(cfg, replicas)
	return cfg
}

func applyContract(cfg *nats.StreamConfig, replicas int) {
	cfg.Name = StreamName
	cfg.Subjects = []string{SubjectPrefix + ">"}
	cfg.Retention = nats.WorkQueuePolicy
	cfg.Storage = nats.FileStorage
	cfg.Discard = nats.DiscardNew
	cfg.Duplicates = StreamDuplicatesWindow
	cfg.MaxAge = StreamMaxAge
	cfg.MaxBytes = StreamMaxBytes
	cfg.Replicas = replicas
}
