package mirrorjobs

import (
	"context"

	"github.com/entirehq/mirror-pipeline/internal/natspub"
	"github.com/entirehq/mirror-pipeline/pkg/gitjobs"
)

const tracerName = "mirrorjobs"

// NatsMsgIDHeader is the JetStream deduplication header.
const NatsMsgIDHeader = natspub.MsgIDHeader

// JetStreamPublisher is the subset of nats.JetStreamContext needed for publish.
type JetStreamPublisher = natspub.JetStreamPublisher

// Publisher publishes canonical Git mirror jobs.
type Publisher struct {
	js JetStreamPublisher
}

// NewPublisher returns a publisher backed by JetStream.
func NewPublisher(js JetStreamPublisher) *Publisher {
	return &Publisher{js: js}
}

// PublishGitSyncJob publishes a sync_repo job for a resolved mirror route.
func (p *Publisher) PublishGitSyncJob(ctx context.Context, route MirrorRoute) error {
	parsed := gitjobs.ParsedSubject{
		Placement:  route.Placement,
		SourceKind: route.SourceKind,
		Op:         gitjobs.OpSyncRepo,
	}
	job := gitjobs.Job{
		Source: route.Source,
		Target: route.Target,
	}
	return natspub.Publish(ctx, p.js, natspub.Publication{
		Tracer:    tracerName,
		SpanName:  "mirror.git.publish",
		ErrKind:   "git mirror job",
		LogMsg:    "Published git mirror job",
		Subject:   gitjobs.Subject(parsed),
		MsgID:     gitjobs.MsgID(parsed, job),
		Marshal:   func() ([]byte, error) { return gitjobs.MarshalFor(parsed.SourceKind, job) },
		SpanAttrs: append(parsed.SpanAttrs(), job.SpanAttrs()...),
		LogAttrs:  append(parsed.LogAttrs(), job.LogAttrs()...),
	})
}

