package gitjobs

import (
	"context"
	"fmt"
	"log/slog"

	"github.com/entireio/go-nuts/natsmsg"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"

	"entire.io/slogutil"
)

const tracerName = "entire.io/core/mirrorrepo/gitjobs"

// Publisher publishes git-sync jobs onto the canonical mirror_git_v1
// stream. mirror-pipeline owns the stream creation; entire-core only
// publishes.
//
// A job goes to the NATS for its target cluster: a Publisher holds a
// default JetStream plus an optional per-target-slug override
// (WithClusterStream). A regional core co-located with a single cell
// leaves the map empty and every job takes the default; a core serving
// several cells in its jurisdiction registers each cell's slug so that
// cell's clones land on its own in-cluster NATS, where the co-located
// mirror-worker consumes.
//
// The destination is encoded in the SUBJECT, but a subject does not cross
// islands: mirror_git_v1 is a separate stream per island with no mirroring or
// leafnode route between them. Publishing a foreign-jurisdiction subject onto
// the local island therefore succeeds at JetStream and is consumed by nobody —
// the silent misroute behind ENT-2082. WithHomeJurisdiction turns that into a
// returned error.
//
// The publish mechanics (producer span, trace-context injection,
// Nats-Msg-Id, bounded PubAck wait) live in the shared
// natsmsg.Publisher; this type owns the domain: subject/job
// construction, the dedup key, and the log line.
type Publisher struct {
	def    natsmsg.Publisher
	bySlug map[string]natsmsg.Publisher
	// home is the jurisdiction whose island the default JetStream belongs to.
	// Empty disables the cross-island guard entirely (dev, tests, and any
	// wiring that has not declared one), preserving the plain default-fallback
	// routing.
	home string
}

// NewPublisher binds a Publisher to a default JetStream context
// (natsmsg.JetStream is the publish slice of nats.JetStreamContext; tests
// stub it). Jobs with no per-slug override registered via WithClusterStream
// publish here.
func NewPublisher(js natsmsg.JetStream) *Publisher {
	return &Publisher{def: newMsgPublisher(js)}
}

// WithClusterStream routes jobs whose target cluster slug equals slug to js
// instead of the default JetStream. Returns the receiver for chaining.
func (p *Publisher) WithClusterStream(slug string, js natsmsg.JetStream) *Publisher {
	if p.bySlug == nil {
		p.bySlug = make(map[string]natsmsg.Publisher)
	}
	p.bySlug[slug] = newMsgPublisher(js)
	return p
}

// WithHomeJurisdiction declares the jurisdiction the default JetStream's island
// serves, arming the cross-island guard: a job for another jurisdiction is
// refused unless that cluster has its own stream registered via
// WithClusterStream. Returns the receiver for chaining.
//
// Without it a foreign-jurisdiction job silently falls back to the default —
// a clean PubAck onto an island where no worker for that destination consumes,
// which is how a cross-jurisdiction `admin mirrors resume` reported success
// while the resync job sat unread until max_age expired it (ENT-2082). The
// guard is jurisdiction-scoped, not slug-scoped, because the default stream
// legitimately serves every unmapped cell of its OWN jurisdiction (the
// single-cell deployment documented on WithClusterStream); only the
// cross-jurisdiction hop has no route at all.
//
// Registering a FOREIGN cluster with WithClusterStream does make this
// publisher route to it — the guard is about the absence of a route, not the
// jurisdiction boundary itself. The runtime error deliberately does not
// advertise that as a remedy: entire-core gates the admin resume on
// jurisdiction alone (Server.mirrorResumeJurisdictionGate), so a foreign route
// here would not unblock the verb that surfaced the failure, and the boundary
// it crosses is the one repoadmin.Router keeps closed on purpose.
func (p *Publisher) WithHomeJurisdiction(jurisdiction string) *Publisher {
	p.home = jurisdiction
	return p
}

func newMsgPublisher(js natsmsg.JetStream) natsmsg.Publisher {
	return natsmsg.Publisher{
		JS:        js,
		Tracer:    otel.Tracer(tracerName),
		Operation: "mirror.git.publish",
	}
}

// publisherFor selects the JetStream a job for the given placement publishes
// to: the per-slug override when registered, else the default. It errors
// instead of falling back when the placement is in another jurisdiction and
// the guard is armed (WithHomeJurisdiction) — the default island has no route
// to that destination, so the fallback would be a misroute, not a delivery.
func (p *Publisher) publisherFor(placement Placement) (natsmsg.Publisher, error) {
	if routed, ok := p.bySlug[placement.ClusterID]; ok {
		return routed, nil
	}
	if p.home != "" && placement.Jurisdiction != "" && placement.Jurisdiction != p.home {
		return natsmsg.Publisher{}, fmt.Errorf(
			"no mirror_git_v1 route to jurisdiction %q (cluster %q): this publisher's default stream is on the %q island and the stream does not cross islands; publish from a core in %q, or register the cluster in ENTIRE_MIRROR_GIT_NATS_URLS_BY_SLUG",
			placement.Jurisdiction, placement.ClusterID, p.home, placement.Jurisdiction)
	}
	return p.def, nil
}

// PublishSyncRepo emits a single sync_repo job for a GitHub-sourced
// mirror. Idempotent on (placement, source, target) via the
// Nats-Msg-Id dedup header — a retry within StreamDuplicatesWindow
// collapses server-side, so the caller doesn't have to coordinate.
// OTel trace context rides the NATS headers so the worker's span
// parents to this publish.
//
// A nil Publisher receiver or nil js panics on call: callers MUST
// wire a publisher, and serve-mode boot enforces it (see
// buildGitJobsPublisher). Silently treating nil as "skip the publish"
// is what stranded EU mirrors in provisioning state.
func (p *Publisher) PublishSyncRepo(ctx context.Context, placement Placement, source Source, target Target) error {
	return p.publish(ctx, placement, SourceKindGithub, source, target, "")
}

// PublishEntireDBSyncRepo emits a single sync_repo job for a native
// mirror: source is the primary's internal by-ID git URL on its home
// cluster (Source.URL; no owner/repo, no minted credential — the
// worker fetches with its client cert). Same idempotency and nil
// semantics as PublishSyncRepo.
func (p *Publisher) PublishEntireDBSyncRepo(ctx context.Context, placement Placement, source Source, target Target) error {
	return p.publish(ctx, placement, SourceKindEntireDB, source, target, "")
}

// PublishEntireDBSyncRepoRepair is PublishEntireDBSyncRepo with a
// caller-supplied nonce appended to the dedup Msg-ID. The resync sweep
// (ADR 20260818-native-mirror-resync-sweep) uses it because the standard
// Msg-ID is constant per (source, target) pair: a repair published inside the
// stream's duplicate window of an earlier identical publish would otherwise
// be silently collapsed and the placement left stale for another pass — the
// same trap mirror-pipeline's rekicker documents. The nonce should be unique
// per publish (a sweep-pass ULID); retries WITHIN one publish attempt still
// collapse because natsmsg retries reuse the message.
func (p *Publisher) PublishEntireDBSyncRepoRepair(ctx context.Context, placement Placement, source Source, target Target, nonce string) error {
	return p.publish(ctx, placement, SourceKindEntireDB, source, target, nonce)
}

// PublishEntireDBNamespaceSyncRepo emits a sync_repo job for the
// Entire-owned refs/heads/entire/native/* namespace (COR-1566): the
// entiredb body shape under the entiredb_ns kind, which the worker
// replicates with a namespace-scoped ref policy. Nonce semantics are
// PublishEntireDBSyncRepoRepair's, and for the same reason — a seed for a
// (source, target) pair that was seeded before, or re-stamped inside the
// duplicate window, must not be collapsed into the earlier one.
func (p *Publisher) PublishEntireDBNamespaceSyncRepo(ctx context.Context, placement Placement, source Source, target Target, nonce string) error {
	return p.publish(ctx, placement, SourceKindEntireDBNamespace, source, target, nonce)
}

func (p *Publisher) publish(ctx context.Context, placement Placement, kind SourceKind, source Source, target Target, msgIDNonce string) error {
	// Resolve the destination stream first: an unroutable placement is a
	// caller bug (or a misconfigured route map), and failing before the
	// marshal keeps the error about the destination rather than the payload.
	dest, err := p.publisherFor(placement)
	if err != nil {
		return err
	}
	parsed := ParsedSubject{
		Placement:  placement,
		SourceKind: kind,
		Op:         OpSyncRepo,
	}
	job := Job{Source: source, Target: target}
