// A job goes to the NATS for its target cluster: a Publisher holds a
// default JetStream plus an optional per-target-slug override
// (WithClusterStream). A regional core co-located with a single cell
// leaves the map empty and every job takes the default; a core serving
// several cells in its jurisdiction registers each cell's slug so that
// cell's clones land on its own in-cluster NATS, where the co-located
// mirror-worker consumes.
//
// The destination is encoded in the SUBJECT, but a subject does not cross
// islands: mirror_git_v1 is a separate stream per island with no mirroring or
// leafnode route between them. Publishing a foreign-jurisdiction subject onto
// the local island therefore succeeds at JetStream and is consumed by nobody —
// the silent misroute behind ENT-2082. WithHomeJurisdiction turns that into a
// returned error.
//
// The publish mechanics (producer span, trace-context injection,
// Nats-Msg-Id, bounded PubAck wait) live in the shared
// natsmsg.Publisher; this type owns the domain: subject/job
// construction, the dedup key, and the log line.
type Publisher struct {
	def    natsmsg.Publisher
	bySlug map[string]natsmsg.Publisher
	// home is the jurisdiction whose island the default JetStream belongs to.
	// Empty disables the cross-island guard entirely (dev, tests, and any
	// wiring that has not declared one), preserving the plain default-fallback
	// routing.
	home string
}

// NewPublisher binds a Publisher to a default JetStream context
// (natsmsg.JetStream is the publish slice of nats.JetStreamContext; tests
// stub it). Jobs with no per-slug override registered via WithClusterStream
// publish here.
func NewPublisher(js natsmsg.JetStream) *Publisher {
	return &Publisher{def: newMsgPublisher(js)}
}

// WithClusterStream routes jobs whose target cluster slug equals slug to js
// instead of the default JetStream. Returns the receiver for chaining.
func (p *Publisher) WithClusterStream(slug string, js natsmsg.JetStream) *Publisher {
	if p.bySlug == nil {
		p.bySlug = make(map[string]natsmsg.Publisher)
	}
	p.bySlug[slug] = newMsgPublisher(js)
	return p
}

// WithHomeJurisdiction declares the jurisdiction the default JetStream's island
// serves, arming the cross-island guard: a job for another jurisdiction is
// refused unless that cluster has its own stream registered via
// WithClusterStream. Returns the receiver for chaining.
//
// Without it a foreign-jurisdiction job silently falls back to the default —
// a clean PubAck onto an island where no worker for that destination consumes,
// which is how a cross-jurisdiction `admin mirrors resume` reported success
// while the resync job sat unread until max_age expired it (ENT-2082). The
// guard is jurisdiction-scoped, not slug-scoped, because the default stream
// legitimately serves every unmapped cell of its OWN jurisdiction (the
// single-cell deployment documented on WithClusterStream); only the
// cross-jurisdiction hop has no route at all.
