	p.home = jurisdiction
	return p
}

func newMsgPublisher(js natsmsg.JetStream) natsmsg.Publisher {
	return natsmsg.Publisher{
		JS:        js,
		Tracer:    otel.Tracer(tracerName),
		Operation: "mirror.git.publish",
