// Package mirrorresume holds the shared "resume a suspended mirror placement"
// recipe: refresh shared-group grants while inheritance is detached, clear
// suspended_at, best-effort re-publish a sync_repo, and re-materialize the
// placement's direct SpiceDB grants. It is used by the admin/webhook resume path (core/api's
// Server.ResumeMirror delegates here) and by the periodic backstop sweep
// (COR-852) that re-arms placements stranded suspended while their upstream is
// legitimately re-attached. Extracting the recipe keeps those two callers from
// drifting on the exact steps and their best-effort ordering.
package mirrorresume

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"entire.io/core/mirrorrepo"
	"entire.io/core/mirrorrepo/gitjobs"
	"entire.io/core/model"
	"entire.io/slogutil"
)

// ErrGrantPreparationFailed marks failures that happen before a placement is
// resumed, while refreshing and converging its shared repo_group grants. The
// admin override may safely degrade these to a detached resume; automatic
// callers continue to fail closed and retry. Errors from the resume mutation
// itself are deliberately not marked.
var ErrGrantPreparationFailed = errors.New("mirror grant preparation failed")

// Placements is the mirrorrepo.Service subset the recipe reads and writes:
// Resume clears suspended_at unconditionally (operator override),
// ResumeWithoutGroupAccess performs the admin-only detached degradation,
// ResumeUnlessOperatorHeld clears it only when no operator hold is present (the
// automatic-resume clear), GetRefByID recovers the upstream coords for the grant
// reconcile, and ListRowsByIDs supplies the jurisdiction/cluster/owner/
// installation the resync kick needs.
type Placements interface {
	Resume(ctx context.Context, id model.RepoID) error
	ResumeWithoutGroupAccess(ctx context.Context, id model.RepoID) error
	ResumeUnlessOperatorHeld(ctx context.Context, id model.RepoID) (bool, error)
	GetRefByID(ctx context.Context, id model.RepoID) (*mirrorrepo.Ref, error)
	ListRowsByIDs(ctx context.Context, ids []model.RepoID) ([]mirrorrepo.ListRow, error)
}

// CollaboratorRefresher re-snapshots a repo's collaborator read-model from the
// live GitHub API and returns the github_repo_id. Satisfied by the perms
// snapshotter and by core/api's MirrorBootstrapper.
type CollaboratorRefresher interface {
	RefreshRepoCollaborators(ctx context.Context, owner, repo string, observedAt time.Time) (githubRepoID int64, err error)
}

// GrantReconciler re-materializes the shared group before resume restores its
// inheritance edge, then the single placement after it becomes active.
// Satisfied by *mirrorperms.Reconciler. removeStale is always true here: a
// resume is an authoritative full replace, so a collaborator who lost access
// during suspension is not re-granted.
type GrantReconciler interface {
	ReconcileGitHubRepoGroupFromFreshSnapshot(ctx context.Context, githubRepoID int64) error
	ReconcileRepo(ctx context.Context, repoID model.RepoID, githubRepoID int64, removeStale bool) error
}

// SyncPublisher re-publishes a sync_repo job so the worker re-confirms the
// clone and the mirror_done_v1 completion advances status off 'processing'.
// Satisfied by *gitjobs.Publisher.
type SyncPublisher interface {
	PublishSyncRepo(ctx context.Context, placement gitjobs.Placement, source gitjobs.Source, target gitjobs.Target) error
}

// AttachmentGate reports whether a placement's upstream is still attached to a
// live (non-suspended) GitHub App installation right now. The backstop sweep
// wires it to githubperms.RepoAttached: enumeration gates attached+live at
// enumeration time, but candidates are processed sequentially against a fresh
// live snapshot each, so a late candidate's upstream can detach/suspend before
// its turn. Re-checking here — as close to the un-suspension as possible —
// keeps a since-detached upstream from being re-armed into an unreachable
// state (the TOCTOU the per-candidate snapshot alone doesn't close). Optional:
// the admin resume path wires no gate, so an operator override always resumes.
type AttachmentGate func(ctx context.Context, githubRepoID int64) (bool, error)

// ResumeOutcome reports what the recipe actually did, so the backstop sweep can
// tell a full resume from a partial one it must not count as a clean success.
type ResumeOutcome struct {
	// GrantsReconciled is true only when the authoritative single-placement
	// reconcile actually ran (fresh snapshot + ReconcileRepo, both succeeding).
	// False when ReconcileRepo errored: the placement is active and inherits the
	// freshly-converged group grants, but its redundant direct tuples stay blank
	// until the main mirror-perms reconcile pass restores them.
	GrantsReconciled bool
	// Skipped is true when the resume was declined before clearing suspended_at,
	// so the placement stays suspended (correctly) — neither an error nor a
	// resume. Two causes: the attachment gate found the upstream detached, or
	// (on an operator-hold-respecting resumer) an operator hold is in place.
	Skipped bool
}

// Resumer runs the shared resume recipe. The publisher is optional, but the
// refresher and reconciler are load-bearing: the shared group's grants must be
// refreshed before Resume restores repo#group inheritance. Without either,
// the placement stays suspended rather than briefly exposing stale access.
type Resumer struct {
	placements        Placements
	publisher         SyncPublisher         // optional
	refresher         CollaboratorRefresher // required to resume safely
	reconciler        GrantReconciler       // required to resume safely
	attached          AttachmentGate        // optional
	honorOperatorHold bool                  // automatic-resume paths set this
}

// Option configures the recipe dependencies. Callers must pass only non-nil
// dependencies: safety checks key on a true nil interface, so wrapping a
// typed-nil would defeat them.
type Option func(*Resumer)

// WithSyncPublisher wires the resync-kick arm. Omit it (or the run-once wiring's
// absent publisher) to skip the kick: a resumed placement stays 'processing'
// until its next organic sync.
func WithSyncPublisher(p SyncPublisher) Option { return func(r *Resumer) { r.publisher = p } }

// WithCollaboratorRefresher wires the load-bearing live-snapshot step. Without
// it ResumeMirror fails closed before clearing suspension.
func WithCollaboratorRefresher(c CollaboratorRefresher) Option {
	return func(r *Resumer) { r.refresher = c }
}

// WithGrantReconciler wires the authoritative group and placement reconciles.
// Without it (or without a refresher) ResumeMirror fails closed.
func WithGrantReconciler(g GrantReconciler) Option { return func(r *Resumer) { r.reconciler = g } }

// WithAttachmentGate wires the optional pre-Resume attachment re-check. The
// backstop sweep supplies it (githubperms.RepoAttached, which post-COR-853
// means attached AND installation-unsuspended); the admin resume path omits it
// so an operator override always resumes. See AttachmentGate for the TOCTOU it
// closes.
func WithAttachmentGate(g AttachmentGate) Option { return func(r *Resumer) { r.attached = g } }

// WithOperatorHoldRespected makes the recipe refuse an operator hold: the clear
// runs through ResumeUnlessOperatorHeld, and a placement whose suspend_source is
// 'operator' is left suspended (ResumeOutcome.Skipped). Every AUTOMATIC resume
// caller sets this — the backstop sweep and the repoops resume consumer

