package fanoutengine

import (
	"sync"
	"time"
)

// memoMaxEntries bounds the memo. Live entries exist only for deliveries in
// redelivery limbo (fetched but not yet Ack'd/Term'd), which JetStream caps at
// the consumer's MaxAckPending — 4096 is comfortably above any configured
// value. Overflow evicts and only costs the optimization (an evicted delivery
// re-publishes everywhere, exactly today's behavior), never correctness.
const memoMaxEntries = 4096

// routeMemo remembers, per in-flight delivery, which regions have already
// returned a successful PubAck from THIS process. dispatchRoutes publishes all
// routes and Naks if any failed; on the ~NakDelay-later redelivery the
// already-successful regions would be re-published — and for mirror_git_v1 the
// 1s dedup window (deliberately narrow, see fleet's mirror-git-v1.yaml) is
// long expired, so every retry re-runs full git syncs in every region that
// already succeeded. The memo skips those regions instead.
//
// In-process only, by design: a redelivery that lands on another replica
// misses the memo and re-publishes everywhere, which is safe (syncs are
// idempotent; streams with wide-enough dedup windows collapse server-side).
// Durable cross-replica tracking isn't worth the coordination — the memo
// turns the common same-replica retry into a no-op and leaves the rest to
// idempotency. The full tradeoff, the rejected alternatives (widening the
// dedup window, a KV-backed durable memo), and the trigger for upgrading to
// the durable variant are in docs/multi-region/fanout-route-memo.md.
//
// Entries are dropped at final disposition (Ack/Term) and expire after ttl —
// an upper bound on how long the same stream message can keep redelivering
// (MaxDeliver × (AckWait + NakDelay)). Expiry matters because a panic-path
// Term has no envelope in scope to forget explicitly.
type routeMemo struct {
	ttl time.Duration
	max int
	now func() time.Time // test seam

	mu      sync.Mutex
	entries map[string]*memoEntry
}

type memoEntry struct {
	regions map[string]struct{}
	touched time.Time
}

func newRouteMemo(ttl time.Duration, maxEntries int) *routeMemo {
	return &routeMemo{ttl: ttl, max: maxEntries, now: time.Now, entries: map[string]*memoEntry{}}
}

// succeeded reports whether region already got a PubAck for deliveryID from
// this process. An empty deliveryID is never memoized (nothing to key on).
func (m *routeMemo) succeeded(deliveryID, region string) bool {
	if deliveryID == "" {
		return false
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	e := m.entries[deliveryID]
	if e == nil {
		return false
	}
	if m.now().Sub(e.touched) > m.ttl {
		delete(m.entries, deliveryID)
		return false
	}
	_, ok := e.regions[region]
	return ok
}

// record notes a successful publish of deliveryID into region.
func (m *routeMemo) record(deliveryID, region string) {
	if deliveryID == "" {
		return
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	e := m.entries[deliveryID]
	if e == nil {
		if len(m.entries) >= m.max {
			m.evictLocked()
		}
		e = &memoEntry{regions: map[string]struct{}{}}
		m.entries[deliveryID] = e
	}
	e.regions[region] = struct{}{}
	e.touched = m.now()
}

// forget drops the delivery's entry — its message reached a final disposition
// (Ack or Term), so no further redelivery can consult it.
func (m *routeMemo) forget(deliveryID string) {
	if deliveryID == "" {
		return
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	delete(m.entries, deliveryID)
}

// evictLocked frees room for one insert: drop every expired entry, and if none
// were expired, drop the least-recently-touched one.
func (m *routeMemo) evictLocked() {
	now := m.now()
	var oldestKey string
	var oldest time.Time
	freed := false
	for k, e := range m.entries {
		if now.Sub(e.touched) > m.ttl {
			delete(m.entries, k)
			freed = true
			continue
		}
		if oldestKey == "" || e.touched.Before(oldest) {
			oldestKey, oldest = k, e.touched
		}
	}
	if !freed && oldestKey != "" {
		delete(m.entries, oldestKey)
	}
}

